{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C10","C17","C20","C05","C41","C104","C84","C67","C09","C50","C147","C142","C124","C168","C145"],
  "contradictory_card_ids": ["C164","C119"],
  "prediction_basis_card_ids": ["C10","C17","C20","C104","C84","C67","C147","C142","C124","C168","C145"],
  "claims": [
    {
      "claim": "Direct human L1 evidence: FK788, an aryloxyacetic acid on a fused bicyclic ring, had 55% oral bioavailability in healthy volunteers; etodolac, an ionizable carboxylic acid, had 80-100% F in humans. These structurally relevant acidic molecules exceed the 20% threshold.",
      "card_ids": ["C10","C17","C20","C05","C41"]
    },
    {
      "claim": "L3 oral-vs-IV exposure: cicaprost, a prostanoid with an OCH2COOH side chain, had oral AUC0-∞ 422 pg·h/ml after 7.6 µg versus IV AUC0-∞ 409 pg·h/ml after 2.1 µg, corresponding to ~100% F; this is direct evidence that an ionized acidic prostanoid can have high oral bioavailability.",
      "card_ids": ["C104","C84"]
    },
    {
      "claim": "L4 absorption context: PGF2α (dinoprost) has aqueous solubility 1.5 mg/mL, high rat jejunal effective permeability at pH 3.5-4.5 (1.46-2.57×10^-4 cm/s), and <20% degradation in intestinal lumen in 30 min, supporting intestinal absorption of prostanoid acids; a micellar formulation improved oral absorption of an acidic compound in dogs, consistent with fed-state enhancement.",
      "card_ids": ["C147","C142","C124","C168","C145"]
    },
    {
      "claim": "L4 low Caco-2 Papp for PGE2 (5.0×10^-7 cm/s) and LTB4 (7.2×10^-7 cm/s) is less transferable because these flexible fatty-acid prostanoids differ from the rigid aryloxyacetic acid query, and Caco-2 Papp is not a direct F measurement; it does not affirmatively establish F<20%.",
      "card_ids": ["C164","C119"]
    },
    {
      "claim": "Fed-state context: food increased propranolol F from 0.27 to 0.46, and fed-state KNI-272 capsule F was 36.4% (4 mg/kg 22.06%), supporting that the fed condition does not lower F below threshold.",
      "card_ids": ["C67","C09","C50"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C147","C142","C124","C168","C145","C164","C119"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific permeability or solubility measurement; L4 analogs differ in pKa, ring system, and side-chain flexibility.",
    "PGF2α jejunal permeability was measured at pH 3.5-4.5 where it is largely neutral; query pKa 3.07 means greater ionization at intestinal pH, limiting direct transfer.",
    "PGE2/LTB4 Caco-2 low permeability may not reflect the rigid aryloxyacetic acid query and is not a direct F measurement.",
    "Fed-state effect on the query is inferred from food/micellar effects on other molecules, not measured directly.",
    "First-pass metabolism and systemic clearance of the query are not experimentally characterized."
  ],
  "decision_summary": "Predicted high (F≥20%) because direct human F evidence for structurally relevant acidic molecules (FK788 55%, etodolac 80-100%) and oral-vs-IV exposure for cicaprost (~100%) outweigh indirect L4 permeability concerns; L4 adds supportive solubility/stability/micellar-absorption context but no affirmative F<20% evidence. Confidence remains high."
}

